import { after } from 'next/server';
import { headers } from 'next/headers';
import { logPageView } from './analytics';

export default async function Home() {
  // Schedule analytics logging AFTER the response is sent
  // This does NOT block the response to the user
  after(async () => {
    const headersList = await headers();
    const userAgent = headersList.get('user-agent') || undefined;

    await logPageView({
      path: '/',
      timestamp: new Date().toISOString(),
      userAgent,
    });
  });

  return (
    <main>
      <h1>Welcome!</h1>
      <p>This page logs analytics without blocking the response.</p>
      <p>The analytics logging happens after the response is sent to you.</p>
    </main>
  );
}

